q("TERRE", "MGRS à 6 chiffres : précision", ["100 m", "1 km", "10 m", "1 m"], "4 chiffres = 1 km ; 8 = 10 m ; 10 = 1 m.")
q("TERRE", "Format de coordonnées donné par un JTAC :", ["MGRS", "DMS", "Degrés décimaux", "Gisement-distance"], "Format standard OTAN au sol.")
q("TERRE", "1 NM =", ["1852 m", "1609 m", "1000 m", "6000 m"], "1 SM = 1609 m.")
q("TERRE", "Circonférence de la Terre :", ["21 600 NM ≈ 40 000 km", "10 800 NM ≈ 20 000 km", "21 600 km ≈ 40 000 NM", "5 400 NM ≈ 10 000 km"], "60 × 360 = 21 600 NM.")
q("TERRE", "1 NM ≈", ["6076 ft", "5280 ft", "3281 ft", "1852 ft"], "Arrondi pratique : 6000 ft.")
q("TERRE", "Conversion rapide NM → km :", ["× 2 − 10 %", "× 2 + 10 %", "÷ 2 − 10 %", "× 1,5"], "km → NM : ÷ 2 + 10 %.")
