# ---- Grand cercle
q("GC", "Un grand cercle est un cercle…", ["Dont le centre est celui de la Terre", "Parallèle à l'équateur", "Passant par les deux pôles uniquement", "Dont le centre est sur l'axe des pôles"], "L'équateur et les méridiens (avec leurs antiméridiens) en sont.")
q("GC", "Le seul parallèle qui est un grand cercle :", ["L'équateur", "Le 45°N", "Les cercles polaires", "Aucun"], "")
q("GC", "Orthodromie :", ["Plus court chemin, cap qui varie", "Plus court chemin, cap constant", "Cap constant, plus long", "Chemin le long d'un parallèle"], "Loxodromie : cap constant, plus longue (sauf équateur et méridiens).")
q("GC", "Loxodromie et orthodromie sont confondues…", ["Sur l'équateur et sur un méridien", "Sur tous les parallèles", "Uniquement près des pôles", "Jamais"], "")
q("GC", "Entre un nœud et un vertex, il y a toujours…", ["90° de longitude", "45° de longitude", "180° de longitude", "90° de latitude"], "Nœud = latitude 0 ; vertex = latitude maximale.")
q("GC", "Les deux vertex d'un grand cercle sont…", ["Antipodes : latitudes opposées, 180° de longitude", "Sur le même méridien, même latitude", "À 90° de longitude, latitudes opposées", "Sur l'équateur, à 180° l'un de l'autre"], "")
q("GC", "Angle entre un grand cercle et l'équateur au nœud :", ["Égal à la latitude du vertex", "Toujours 45°", "Égal à 90° moins la latitude du vertex", "Égal à la longitude du vertex"], "")
q("GC", "Route vraie au passage d'un vertex :", ["090° ou 270°", "000° ou 180°", "045° ou 225°", "Elle n'est pas définie"], "On y est tangent au parallèle.")
q("GC", "5400 NM correspondent à…", ["90° d'arc, ¼ de grand cercle", "180° d'arc, ½ grand cercle", "45° d'arc, ⅛ de grand cercle", "360° d'arc, le tour complet"], "10 800 NM = antipode.")
q("GC", "Où la route vraie varie-t-elle le plus vite sur un grand cercle ?", ["Aux vertex", "Aux nœuds", "Partout pareil", "Sur l'équateur"], "ΔRv ≈ ΔG × sin(latitude) ; nulle aux nœuds.")
# ---- Calculs
q("CALC", "Départ N45°32' E005°12', 100 NM au 360°. Arrivée ?", ["N47°12' E005°12'", "N46°32' E005°12'", "N45°32' E006°52'", "N47°12' E006°52'"], "100' = 1°40' ; 45°32' + 1°40' = 47°12'.")
q("CALC", "Sur l'équateur, 250 NM vers l'est depuis W024°10' :", ["W020°00'", "W028°20'", "E020°00'", "W021°40'"], "Sur l'équateur, 1' de longitude = 1 NM. Vers l'est en W : on soustrait.")
q("CALC", "Le long d'un parallèle, Δlongitude (en ') =", ["Distance / cos(latitude)", "Distance × cos(latitude)", "Distance / sin(latitude)", "Distance × sin(latitude)"], "À 45°, 1 NM ≈ 1,41' de longitude.")
q("CALC", "600 NM plein ouest depuis N45°00' E002°15' :", ["N45°00' W011°53'", "N45°00' W007°45'", "N45°00' E012°15'", "N45°00' W012°08'"], "600 / 0,707 ≈ 848' = 14°08' ; on franchit Greenwich : 14°08' − 2°15'.")
q("CALC", "1800 NM au 360° depuis S06°35' W005°10' :", ["N23°25' W005°10'", "N36°35' W005°10'", "S23°25' W005°10'", "N30°00' W005°10'"], "1800' = 30° ; 30° − 6°35' dans l'hémisphère Nord.")
q("CALC", "150 kt sol pendant 1 h 30 : distance", ["225 NM", "200 NM", "250 NM", "180 NM"], "1 kt = 1 NM/h.")
q("CALC", "Depuis le nœud N0° E165°, 5400 NM à la route 300° :", ["N30° E075°", "N60° E075°", "N30° W105°", "N30° E105°"], "On arrive au vertex : latitude = 30° (300° est à 30° de l'ouest), 90° de longitude plus à l'ouest.")
q("CALC", "10 800 NM sur un grand cercle depuis N40° E165° :", ["S40° W015°", "N40° W015°", "S40° E015°", "S40° W165°"], "Demi grand cercle = antipode : latitude opposée, longitude ± 180°.")
q("CALC", "E169°23' → W172°55' au même parallèle : Δlongitude", ["17°42'", "342°18'", "3°32'", "7°05'"], "Le plus court passe par l'antiméridien : 10°37' + 7°05'.")
q("CALC", "250 km/h ≈", ["135 kt", "463 kt", "155 kt", "125 kt"], "÷ 1,852. Convertir avant d'ajouter le vent.")
# ---- Propriétés, échelle
q("PROP", "Une projection CONFORME conserve…", ["Les angles", "Les surfaces", "Les distances", "Les formes à grande échelle"], "Équivalente = surfaces ; équidistante = distances (dans certaines directions).")
q("PROP", "Combinaison impossible :", ["Conforme et équivalente", "Conforme et équidistante", "Équivalente et équidistante", "Conforme et quasi orthodromique"], "")
q("PROP", "Pourquoi toutes les cartes aéro sont conformes ?", ["Pour mesurer des routes justes", "Pour mesurer des surfaces justes", "Pour avoir une échelle constante", "Pour que les pôles soient visibles"], "")
