q("PROP", "Une carte à GRANDE échelle :", ["Petit dénominateur, petite zone, beaucoup de détails", "Grand dénominateur, grande zone, peu de détails", "Petit dénominateur, grande zone, peu de détails", "Grand dénominateur, petite zone, beaucoup de détails"], "Ex. 1:50 000.")
q("PROP", "Les 3 critères d'une projection bien choisie :", ["Conforme, quasi orthodromique, quasi équidistante", "Équivalente, orthodromique, conforme", "Conforme, loxodromique, équivalente", "Équidistante, équivalente, orthodromique"], "On utilise la zone proche du contact, la moins déformée.")
# ---- Projections
q("PROJ", "Mercator : surface de projection", ["Cylindre tangent à l'équateur", "Cylindre tangent à un méridien", "Cône sécant sur deux parallèles", "Plan tangent au pôle"], "")
q("PROJ", "Mercator : méridiens et parallèles", ["Droites perpendiculaires", "Droites convergentes et arcs", "Droites rayonnantes et cercles", "Courbes et droites"], "Les parallèles s'écartent avec la latitude.")
q("PROJ", "Mercator : échelle à 60° de latitude", ["Agrandie 2 fois", "Réduite de moitié", "Exacte", "Agrandie 1,5 fois"], "Échelle en 1/cos(latitude).")
q("PROJ", "Sur une Mercator, une droite représente…", ["Une loxodromie", "Une orthodromie", "Un petit cercle", "Un parallèle seulement"], "L'orthodromie est une courbe creuse vers l'équateur.")
q("PROJ", "Mesurer une distance sur une Mercator :", ["Échelle des latitudes à hauteur du trajet", "Échelle graphique fixe en bas de carte", "Échelle des longitudes sur l'équateur", "Règle graduée en km"], "1' de latitude = 1 NM.")
q("PROJ", "Mercator : zone quasi orthodromique et équidistante", ["Entre 20°S et 20°N", "Entre 40° et 60°", "Au-delà de 70°", "Entre 0° et 72°"], "Elle existe jusqu'à 72°.")
q("PROJ", "Lambert : surface de projection", ["Cône sécant sur deux parallèles standards", "Cône tangent à l'équateur", "Cylindre sécant sur deux parallèles", "Plan sécant au pôle"], "")
q("PROJ", "Lambert : méridiens", ["Droites convergentes vers le pôle", "Droites parallèles entre elles", "Droites rayonnantes sur 360°", "Arcs de cercle concentriques"], "Parallèles = arcs de cercle concentriques.")
q("PROJ", "Lambert : échelle entre les parallèles standards", ["Légèrement trop petite", "Légèrement trop grande", "Exacte", "Doublée"], "Exacte sur les parallèles standards ; trop grande à l'extérieur.")
q("PROJ", "Sur une Lambert, une droite ≈", ["Une orthodromie", "Une loxodromie", "Un parallèle", "Un petit cercle"], "La loxodromie y est une courbe creuse vers le pôle.")
q("PROJ", "Sur une Lambert, on mesure une route…", ["Au méridien du milieu du trajet", "Au méridien de départ", "Au méridien d'arrivée", "Sur le parallèle standard"], "La convergence des méridiens fausse la mesure au départ.")
q("PROJ", "Lambert : latitudes d'utilisation", ["4° à 72°", "0° à 20°", "70° à 90°", "20° à 50° seulement"], "Carte OACI 1:500 000, ONC, TPC, radionav.")
q("PROJ", "Stéréographique polaire : méridiens", ["Droites rayonnantes depuis le pôle", "Droites parallèles", "Droites convergentes vers un sommet", "Courbes concaves"], "Parallèles : cercles concentriques. Usage au-delà de 70-75°.")
q("PROJ", "Stéréographique polaire : convergence des méridiens", ["Égale à l'écart de longitude", "Nulle", "Égale à Δlong × sin(lat moyenne)", "Constante à 45°"], "")
q("PROJ", "UTM :", ["Cylindre transverse, 60 fuseaux de 6°", "Cylindre direct, 60 fuseaux de 6°", "Cylindre transverse, 36 fuseaux de 10°", "Cône sécant, 60 fuseaux de 6°"], "Cartes topo 1:50 000 et carroyage MGRS.")
q("PROJ", "Limite de l'UTM :", ["Les fuseaux ne se raccordent pas", "Inutilisable sous 60° de latitude", "Échelle fausse au méridien central", "Les angles ne sont pas conservés"], "")
